function page(r,title,body,status=200){const path=r.req.path,publicOrder=path.startsWith('/m/')||path.startsWith('/seguimiento/')||path.startsWith('/pedido/'),merchant=path==='/panel'||path==='/exportar',admin=path.startsWith('/admin');const nav=path==='/'?'':publicOrder?'<nav><a href="/explorar">Explorar</a></nav>':admin?'':merchant&&r.req.shop?'<nav><a href="/explorar">Explorar</a></nav>':path==='/registro'?'<nav><a href="/panel">Iniciar sesión</a></nav>':merchant?'<nav><a href="/registro">Registrarse</a></nav>':'<nav><a href="/explorar">Explorar</a><a href="/repartidor">Repartir</a><a href="/panel">Mi negocio</a></nav>';r.status(status).send('<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>P-deme</title><link rel="icon" href="/brand/logo.svg" type="image/svg+xml"><link rel="manifest" href="'+(path.startsWith('/repartidor')||(path==='/instalar'&&r.req.query.role==='driver')?'/manifest-repartidor.webmanifest':'/manifest.webmanifest')+'"><meta name="theme-color" content="#6D28FF"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="default"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><script src="/app-client.js" defer></script><style>'+css+'</style></head><body><header><a id="brand-home" href="/" aria-label="Inicio de P-deme"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" aria-hidden="true"><rect width="80" height="80" rx="23" fill="#6D28FF"/><path fill="#fff" fill-rule="evenodd" d="M21 64V25c0-5 4-9 9-9h15c13 0 23 9 23 21S58 58 45 58H33L21 69zM34 29v16h11c5 0 9-3 9-8s-4-8-9-8z"/><path d="m58 12 5-7m7 13 7-3" stroke="#fff" stroke-width="3" stroke-linecap="round"/></svg>P-deme</a>'+nav+'</header><main>'+body+'</main><footer class="footer"><a href="/privacidad">Privacidad</a> · <a href="/instalar">Instalar aplicación</a></footer></body></html>')}
