 page(r,s.name,'<div class="store-page">'+top+form('/pedido/'+s.slug,'<div class="store-layout">'+items+checkout+'</div>')+'</div>'+'<button class="mobile-cart" id="mobile" onclick="document.querySelector(\'#cart\').scrollIntoView({behavior:\'smooth\'})"><span id="mobileCount">Ver pedido</span><span id="mobileSum"></span></button><style>[hidden]{display:none!important}</style>'+script);
