 const shops=await all('SELECT s.id,s.name,s.slug,s.email,s.billing_status,s.billing_until,s.billing_note,s.platform_blocked,(SELECT COUNT(*) FROM orders o WHERE o.shop=s.id) AS orders,(SELECT COUNT(*) FROM products p WHERE p.shop=s.id) AS products FROM shops s ORDER BY s.id DESC');
