 page(r,'Administración','<div class="row between"><div><h1>Administración general</h1><a href="/admin/repartidores">Repartidores</a></div>'+form('/admin/logout','<button class="secondary">Salir</button>')+'</div><div class="grid"><div class="card stat"><small>Comercios</small><h1>'+shops.length+'</h1></div><div class="card stat"><small>Suscripciones activas</small><h1>'+shops.filter(x=>x.billing_status==='active').length+'</h1></div><div class="card stat"><small>Cobros registrados este mes</small><h1>'+cash(Number(m.total))+'</h1></div></div>'+panel+'<div class="card"><h2>Comercios registrados</h2><input id="admin-search" type="search" placeholder="Buscar comercio o correo" oninput="document.querySelectorAll(\'tr[data-shop]\').forEach(x=>x.hidden=!x.dataset.shop.includes(this.value.toLowerCase()))"><div class="scroll-table"><table class="admin-table"><thead><tr><th>Comercio</th><th>Suscripción</th><th>Pedidos</th><th>Vigencia</th><th></th></tr></thead><tbody>'+shops.map(s=>'<tr data-shop="'+E((s.name+' '+s.email).toLowerCase())+'"><td><b>'+E(s.name)+'</b><br><small>'+E(s.email)+'</small></td><td><span class="pill '+(s.platform_blocked?'status-closed':'')+'">'+E(s.platform_blocked?'Suspendido':billingNames[s.billing_status]||s.billing_status)+'</span></td><td>'+s.orders+'</td><td>'+E(dateValue(s.billing_until)||'Sin fecha')+'</td><td><a href="/admin?shop='+s.id+'">Gestionar</a></td></tr>').join('')+'</tbody></table></div>'+(!shops.length?'<p>No hay comercios registrados.</p>':'')+'</div><div class="card"><h2>Historial de cobros</h2><div class="scroll-table"><table class="admin-table"><thead><tr><th>Negocio</th><th>Fecha</th><th>Importe</th><th>Referencia</th></tr></thead><tbody>'+payments.map(p=>'<tr><td>'+E(p.name)+'</td><td>'+E(dateValue(p.paid_on))+'</td><td>'+cash(p.amount)+'</td><td>'+E(p.note)+'</td></tr>').join('')+'</tbody></table></div>'+(!payments.length?'<p>No se han registrado cobros.</p>':'')+'</div><style>[hidden]{display:none!important}</style>');
